    k = int(data[0])
    words = data[1:1 + k]
    base = [0] * 26
    for ch in words[0]:
        base[ord(ch) - ord('a')] += 1
    for w in words[1:]:
        cur = [0] * 26
        for ch in w:
            cur[ord(ch) - ord('a')] += 1
        for i in range(26):
            if cur[i] < base[i]:
                base[i] = cur[i]
    out = []
    for i in range(26):
        out.extend([chr(ord('a') + i)] * base[i])
    print(' '.join(out))


